package com.adib.maintenance;
import android.app.Activity;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Durable property patches. Comments are never watched. Creation is never blindly retried. */
final class TaskAutosave {
 interface Collect{JSONObject get()throws Exception;} interface Send{JSONObject call(String method,String path,JSONObject body)throws Exception;} interface Apply{void saved(JSONObject body,JSONObject result,boolean created);}
 static final ExecutorService IO=Executors.newSingleThreadExecutor();static final Set<String> active=Collections.synchronizedSet(new HashSet<>());
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("adib_autosave_"+DirectRuntime.scopeHash(DirectConfig.scope(c)),0);}
 static JSONObject read(Context c,String key){try{return new JSONObject(prefs(c).getString(key,"{}"));}catch(Exception e){return new JSONObject();}}
 static boolean same(Object a,Object b){return String.valueOf(a).equals(String.valueOf(b));}
 static void replay(Context c,Send send){for(String key:prefs(c).getAll().keySet()){if(active.contains(key))continue;JSONObject row=read(c,key);if(row.optBoolean("fresh")||row.optBoolean("blocked"))continue;IO.execute(()->{if(!active.add(key))return;try{JSONObject result=send.call("PATCH",row.optString("path"),row.getJSONObject("body"));if(result!=null&&same(read(c,key).opt("body"),row.opt("body")))prefs(c).edit().remove(key).commit();}catch(Exception ignored){}finally{active.remove(key);}});}}
 final Activity activity;final android.content.SharedPreferences durablePrefs;final String connectionScope;final String key,path;final Collect collect;final Send send;final Apply apply;final TextView status;final Handler handler=new Handler(Looper.getMainLooper());JSONObject base,uiBase;String id;boolean fresh,dirty=false,createRequested=false,detached=false;long version=0;Runnable timer;
 TaskAutosave(Activity a,String path,String id,boolean fresh,Collect collect,Send send,Apply apply,TextView status){this.activity=a;this.connectionScope=DirectConfig.scope(a);this.durablePrefs=prefs(a);this.path=path;this.id=id;this.fresh=fresh;this.collect=collect;this.send=send;this.apply=apply;this.status=status;key=path+":"+(fresh?"draft:"+UUID.randomUUID():id);try{base=collect.get();}catch(Exception e){base=new JSONObject();}try{uiBase=new JSONObject(base.toString());}catch(Exception e){uiBase=new JSONObject();}active.add(key);status.setOnClickListener(v->{JSONObject row=readHere();if(row.optBoolean("fresh")&&row.optBoolean("blocked")){new android.app.AlertDialog.Builder(activity).setMessage("Обновите список и сверьте задачу в Notion. Ответ создания неизвестен; повторное создание заблокировано.").setPositiveButton("Понятно",null).show();return;}if(row.optBoolean("blocked")){new android.app.AlertDialog.Builder(activity).setMessage("Проверьте текущие значения в Notion. Применить локальные изменения поверх них?").setNegativeButton("Отмена",null).setPositiveButton("Применить",(d,w)->{try{row.put("blocked",false);row.getJSONObject("body").put("autosaveBase",new JSONObject());durablePrefs.edit().putString(key,row.toString()).commit();flush(null);}catch(Exception ignored){}}).show();}else flush(null);});status.setVisibility(View.VISIBLE);status.setText(readHere().has("body")?"На устройстве есть ожидающие изменения":fresh?"Черновик. Нажмите «Создать», чтобы добавить задачу":"Изменения сохраняются автоматически");}
 JSONObject readHere(){try{return new JSONObject(durablePrefs.getString(key,"{}"));}catch(Exception e){return new JSONObject();}}
 void watch(View view){if(view instanceof EditText)((EditText)view).addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){changed(1500);}public void afterTextChanged(Editable e){}});else if(view instanceof Spinner)((Spinner)view).setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long row){changed(100);}public void onNothingSelected(android.widget.AdapterView<?> p){}});else if(view instanceof CheckBox)((CheckBox)view).setOnCheckedChangeListener((b,checked)->changed(100));else if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)watch(((ViewGroup)view).getChildAt(i));}
 void changed(long delay){if(detached)return;dirty=true;version++;if(timer!=null)handler.removeCallbacks(timer);if(!store()||fresh)return;timer=()->flush(null);handler.postDelayed(timer,delay);}
 boolean store(){if(detached)return false;if(!connectionScope.equals(DirectConfig.scope(activity))){status.setText("Подключение изменилось. Очередь предыдущего пространства сохранена.");return false;}if(!dirty)return false;try{JSONObject current=collect.get(),patch=new JSONObject().put("id",id),expected=new JSONObject();if(current.has("sourceKey"))patch.put("sourceKey",current.get("sourceKey"));int fields=0;for(Iterator<String> it=current.keys();it.hasNext();){String field=it.next();if(field.equals("id")||field.equals("sourceKey"))continue;if(fresh||!same(current.opt(field),uiBase.opt(field))){patch.put(field,current.get(field));if(base.has(field))expected.put(field,base.get(field));fields++;}}if(fields==0)return false;if(fresh)patch.put("autosaveOperationId",key.substring(key.indexOf("draft:")+6));else patch.put("autosaveBase",expected);
 JSONObject prior=readHere();JSONObject old=prior.optJSONObject("body");if(old!=null)for(Iterator<String> it=old.keys();it.hasNext();){String k=it.next();if(!patch.has(k))patch.put(k,old.get(k));}JSONObject row=new JSONObject().put("path",path).put("fresh",fresh).put("body",patch).put("blocked",prior.optBoolean("blocked"));if(prior.has("error"))row.put("error",prior.get("error"));if(!durablePrefs.edit().putString(key,row.toString()).commit())throw new Exception("Нет места для локального сохранения");status.setText(row.optBoolean("blocked")?row.optString("error","Требуется проверка сохранения"):fresh?"Черновик сохранён на устройстве · нажмите «Создать»":"Сохранено на устройстве · ожидает отправки");return true;}catch(Exception e){status.setText(e.getMessage());return false;}}
 boolean busy=false;
 void flush(Runnable done){if(detached)return;if(!connectionScope.equals(DirectConfig.scope(activity)))return;if(timer!=null)handler.removeCallbacks(timer);if(busy)return;JSONObject row=readHere();if(row.optBoolean("fresh")&&!createRequested){status.setText("Нажмите «Создать», чтобы добавить задачу");return;}if(!row.has("body")){if(done!=null)done.run();return;}if(row.optBoolean("blocked")){status.setText(row.optString("error","Создание требует проверки. Сверьте список задач."));return;}busy=true;status.setText("Сохраняю…");long sentVersion=version;IO.execute(()->{try{JSONObject sent=row.getJSONObject("body");boolean create=row.optBoolean("fresh");if(create){row.put("blocked",true).put("error","Ответ создания не получен. Сверьте список задач перед повтором.");durablePrefs.edit().putString(key,row.toString()).commit();}JSONObject result=send.call(create?"POST":"PATCH",path,sent);if(result==null||create&&result.optString("id").isEmpty())throw new Exception("Нет подтверждённого ID задачи. Повторное создание заблокировано.");handler.post(()->{busy=false;try{id=result.optString("id",id);fresh=false;for(Iterator<String> it=sent.keys();it.hasNext();){String k=it.next();if(!k.startsWith("autosave")&&!k.equals("id")) {base.put(k,sent.get(k));try{JSONObject current=collect.get();if(same(current.opt(k),sent.opt(k)))uiBase.put(k,sent.get(k));}catch(Exception ignored){}}}durablePrefs.edit().remove(key).commit();apply.saved(sent,result,create);status.setText("Все изменения сохранены");if(version!=sentVersion){store();flush(done);}else if(done!=null)done.run();}catch(Exception e){status.setText("Ошибка: "+e.getMessage());}});}catch(Exception e){handler.post(()->{busy=false;try{JSONObject latest=readHere();boolean blocked=row.optBoolean("fresh")||e instanceof TaskManagementActivity.ApiError&&("AUTOSAVE_CONFLICT".equals(((TaskManagementActivity.ApiError)e).code)||"TASK_CREATE_PARTIAL".equals(((TaskManagementActivity.ApiError)e).code));latest.put("blocked",blocked).put("error",e.getMessage());durablePrefs.edit().putString(key,latest.toString()).commit();status.setText("Сохранено на устройстве · "+e.getMessage());if(!blocked){timer=()->flush(null);handler.postDelayed(timer,10000);}}catch(Exception ignored){}});}});}
 void detach(){detached=true;handler.removeCallbacksAndMessages(null);active.remove(key);}
}
